Engine*engine_init(int threads){Engine*e=calloc(1,sizeof(Engine));if(!e)return NULL;e->cap=512;e->checks=calloc(e->cap,sizeof(Check));e->nchecks=0;e->check_counts=calloc(e->cap,sizeof(int));e->check_times=calloc(e->cap,sizeof(double));e->total_issues=0;e->threads=threads>0?threads:1;e->verbose=0;return e;}
void engine_register_check(Engine*e,Check c){if(e->nchecks>=e->cap){e->cap*=2;e->checks=realloc(e->checks,e->cap*sizeof(Check));e->check_counts=realloc(e->check_counts,e->cap*sizeof(int));e->check_times=realloc(e->check_times,e->cap*sizeof(double));}e->checks[e->nchecks++]=c;}
