void engine_set_verbose(Engine*e,int v){e->verbose=v;}
void engine_run_check(Engine*e,Check*ck,SourceFile*f,Project*p,int idx){if(!e||!ck||!f||!p)return;Issue iss;memset(&iss,0,sizeof(iss));double start_time=clock();int cnt=ck->func(f,p,&iss);double end_time=clock();if(cnt>0){if(e->verbose){code_scan_printf("[CHECK] %s found %d issues in %s\n",ck->name,cnt,f->path);}e->total_issues+=cnt;e->check_counts[idx]+=cnt;if(f->nissues<MTHOS_MAX_ISSUES){snprintf(iss.loc.file,sizeof(iss.loc.file),"%s",f->path);f->issues[f->nissues++]=iss;}}e->check_times[idx]+=(end_time-start_time)/CLOCKS_PER_SEC;}
int engine_analyze_file(Engine*e,SourceFile*f,Project*p){if(!e||!f||!p)return 0;int found=0;for(int i=0;i<e->nchecks;i++){Check*ck=&e->checks[i];if(ck->lang&&ck->lang!=f->lang)continue;int prev=e->total_issues;engine_run_check(e,ck,f,p,i);if(e->total_issues>prev)found=1;}return found;}
typedef struct{Engine*e;SourceFile**files;int start;int end;Project*p;int*results;}ThreadData;
static void*analyze_thread(void*arg){ThreadData*td=(ThreadData*)arg;int total=0;for(int i=td->start;i<td->end;i++){if(td->files[i]){total+=engine_analyze_file(td->e,td->files[i],td->p);}}*(td->results)=total;return NULL;}
int engine_analyze_project(Engine*e,Project*p){if(!e||!p)return 0;p->analysis_time=clock();int total=0;if(e->threads>1&&p->nfiles>1){int nthreads=e->threads<p->nfiles?e->threads:p->nfiles;ThreadData*td=calloc(nthreads,sizeof(ThreadData));pthread_t*threads=calloc(nthreads,sizeof(pthread_t));int*results=calloc(nthreads,sizeof(int));int chunk=p->nfiles/nthreads;for(int i=0;i<nthreads;i++){td[i].e=e;td[i].files=p->files;td[i].start=i*chunk;td[i].end=(i==nthreads-1)?p->nfiles:(i+1)*chunk;td[i].p=p;td[i].results=&results[i];pthread_create(&threads[i],NULL,analyze_thread,&td[i]);}for(int i=0;i<nthreads;i++){pthread_join(threads[i],NULL);total+=results[i];}free(td);free(threads);free(results);}else{for(int i=0;i<p->nfiles;i++){if(p->files[i])total+=engine_analyze_file(e,p->files[i],p);}}p->analysis_time=(clock()-p->analysis_time)/CLOCKS_PER_SEC;e->total_issues=total;return total;}
void engine_print_stats(Engine*e){if(!e)return;code_scan_printf("Analysis Engine Statistics:\n");code_scan_printf("  Total checks: %d\n",e->nchecks);code_scan_printf("  Total issues found: %d\n",e->total_issues);code_scan_printf("  Check details:\n");for(int i=0;i<e->nchecks;i++){if(e->check_counts[i]>0){code_scan_printf("    %-40s %5d issues  %6.3fs\n",e->checks[i].name,e->check_counts[i],e->check_times[i]);}}}
void engine_free(Engine*e){if(!e)return;free(e->checks);free(e->check_counts);free(e->check_times);free(e);}
